//! Browser entry point: a thin `wasm-bindgen` shell around [`sim_api::Api`].
//!
//! No logic lives here. Every call takes and returns JSON strings; each result is the
//! contract's `Result` shape, `{"ok":true,"value":...}` or `{"ok":false,"error":{"code","message"}}`.
//! The content (`params.json`, initial town, systems, `levers.json`) is compiled into
//! `sim-api`, so the browser needs no file access.
//!
//! Unsafe code: this crate has none of its own (`deny`); the code generated by the
//! `wasm-bindgen` macros is what needs it, which is why the crate does not use the workspace
//! `forbid`. Panics: wasm is built with `panic=abort`, so a panic cannot be turned into an
//! error value. Inputs are validated by `sim-api` instead (it never lets bad input reach the
//! engine), and a panic hook records the message for [`last_panic`], which the JS side reads
//! after catching the resulting `RuntimeError`.
use serde::Serialize;
use sim_api::api::parse_commands;
use sim_api::error::code;
use sim_api::{Api, ApiError, ApiResult};
use sim_params::ContentJson;
use std::cell::RefCell;
use wasm_bindgen::prelude::*;

thread_local! {
    static LAST_PANIC: RefCell<String> = const { RefCell::new(String::new()) };
}

/// Install the panic hook (idempotent). Called by the JS wrapper right after loading.
#[wasm_bindgen]
pub fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        LAST_PANIC.with(|p| *p.borrow_mut() = info.to_string());
    }));
}

/// The message of the last panic, or an empty string.
#[wasm_bindgen]
pub fn last_panic() -> String {
    LAST_PANIC.with(|p| p.borrow().clone())
}

#[derive(Serialize)]
#[serde(untagged)]
enum Wire<T: Serialize> {
    Ok { ok: bool, value: T },
    Err { ok: bool, error: ApiError },
}

fn wrap<T: Serialize>(r: ApiResult<T>) -> String {
    let wire = match r {
        Ok(value) => Wire::Ok { ok: true, value },
        Err(error) => Wire::Err { ok: false, error },
    };
    serde_json::to_string(&wire).unwrap_or_else(|e| {
        format!(
            r#"{{"ok":false,"error":{{"code":"{}","message":"cannot serialise the result: {}"}}}}"#,
            code::BAD_STATE,
            e.to_string().replace('"', "'")
        )
    })
}

fn not_started() -> ApiError {
    ApiError::new(code::BAD_REQUEST, "call init(seed) first")
}

/// One game. The JS wrapper holds a single instance.
#[wasm_bindgen]
pub struct WasmSim {
    api: Option<Api>,
}

impl Default for WasmSim {
    fn default() -> Self {
        Self::new()
    }
}

#[wasm_bindgen]
impl WasmSim {
    #[wasm_bindgen(constructor)]
    pub fn new() -> WasmSim {
        WasmSim { api: None }
    }

    /// Start a game. `seed` is a non-negative integer below 2^53. `params_json`, if given,
    /// replaces `content/params.json` (the other content files stay embedded).
    /// Returns `Result<Snapshot>`.
    pub fn init(&mut self, seed: f64, params_json: Option<String>) -> String {
        wrap(self.start(seed, params_json))
    }

    /// `Result<LeverInfo[]>`.
    pub fn levers(&self) -> String {
        wrap(self.get().map(|a| a.levers().to_vec()))
    }

    /// `Result<ActionInfo[]>`.
    pub fn actions(&self) -> String {
        wrap(self.get().map(|a| a.actions().to_vec()))
    }

    /// `Result<Snapshot>`.
    pub fn snapshot(&self) -> String {
        wrap(self.get().map(|a| a.snapshot()))
    }

    /// `Result<CommandPreview[]>` for a JSON array of commands.
    pub fn preview(&self, commands_json: &str) -> String {
        wrap(
            self.get()
                .and_then(|a| parse_commands(commands_json).and_then(|c| a.preview(&c))),
        )
    }

    /// `Result<TurnResult>` for a JSON array of commands.
    pub fn submit_turn(&mut self, commands_json: &str) -> String {
        wrap(self.get_mut().and_then(|a| {
            let cmds = parse_commands(commands_json)?;
            a.submit_turn(&cmds)
        }))
    }

    /// `Result<{refundPc, snapshot}>`.
    pub fn cancel_pending(&mut self, id: u32) -> String {
        wrap(self.get_mut().and_then(|a| a.cancel_pending(id)))
    }

    /// `Result<string>`: the opaque save blob.
    pub fn export_state(&self) -> String {
        wrap(self.get().and_then(|a| a.export_state()))
    }

    /// `Result<Snapshot>`; on error the game is untouched.
    pub fn import_state(&mut self, blob: &str) -> String {
        wrap(self.get_mut().and_then(|a| a.import_state(blob)))
    }
}

impl WasmSim {
    fn get(&self) -> ApiResult<&Api> {
        self.api.as_ref().ok_or_else(not_started)
    }

    fn get_mut(&mut self) -> ApiResult<&mut Api> {
        self.api.as_mut().ok_or_else(not_started)
    }

    fn start(&mut self, seed: f64, params_json: Option<String>) -> ApiResult<sim_api::Snapshot> {
        let valid = seed.is_finite()
            && seed >= 0.0
            && seed.fract() == 0.0
            && seed < 9_007_199_254_740_992.0;
        if !valid {
            return Err(ApiError::new(
                code::BAD_REQUEST,
                "seed must be a non-negative integer below 2^53",
            ));
        }
        let base = sim_api::content::default_content();
        let content = match params_json.as_deref() {
            Some(p) => ContentJson { params: p, ..base },
            None => base,
        };
        let api = Api::from_content(&content, sim_api::content::LEVERS, seed as u64)?;
        let snap = api.snapshot();
        self.api = Some(api);
        Ok(snap)
    }
}
